export default class Db{constructor(){null===localStorage.getItem("id")&&localStorage.setItem("id",0)}getNextId(){let e=localStorage.getItem("id");return parseInt(e)+1}grave(e){let t=this.getNextId();localStorage.setItem(t,JSON.stringify(e)),localStorage.setItem("id",t)}retrieveAllRecords(){let e=[],t=localStorage.getItem("id");for(let r=1;r<=t;r++){let t=JSON.parse(localStorage.getItem(r));null!==t&&(t.id=r,e.push(t),console.log("Recuperou despesas"))}return e}search(e){return this.records.filter((t=>Object.keys(e).every((r=>t[r]===e[r]||""===e[r]))))}remove(e){localStorage.removeItem(e)}}